-- App shell themes: a named set of images for named slots, chosen per member.
-- System themes are seeded; custom themes are generated by members later.

CREATE TABLE IF NOT EXISTS public.themes (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  slug text NOT NULL UNIQUE,
  name text NOT NULL,
  kind text NOT NULL DEFAULT 'system' CHECK (kind IN ('system', 'custom')),
  owner_user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE,
  tint text,
  is_published boolean NOT NULL DEFAULT false,
  sort_order integer NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.theme_images (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  theme_id uuid NOT NULL REFERENCES public.themes(id) ON DELETE CASCADE,
  slot text NOT NULL,
  image_url text NOT NULL,
  s3_key text,
  prompt text,
  width integer,
  height integer,
  sort_order integer NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS theme_images_theme_slot_idx ON public.theme_images (theme_id, slot, sort_order);

ALTER TABLE public.user_accounts
  ADD COLUMN IF NOT EXISTS theme_id uuid REFERENCES public.themes(id) ON DELETE SET NULL;

ALTER TABLE public.themes ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.theme_images ENABLE ROW LEVEL SECURITY;

-- Anyone signed in can read published system themes and their own custom ones.
DROP POLICY IF EXISTS themes_read ON public.themes;
CREATE POLICY themes_read ON public.themes
  FOR SELECT TO authenticated
  USING (is_published OR owner_user_id = auth.uid());

DROP POLICY IF EXISTS themes_own_write ON public.themes;
CREATE POLICY themes_own_write ON public.themes
  FOR ALL TO authenticated
  USING (owner_user_id = auth.uid())
  WITH CHECK (owner_user_id = auth.uid() AND kind = 'custom');

DROP POLICY IF EXISTS theme_images_read ON public.theme_images;
CREATE POLICY theme_images_read ON public.theme_images
  FOR SELECT TO authenticated
  USING (EXISTS (
    SELECT 1 FROM public.themes t
    WHERE t.id = theme_images.theme_id
      AND (t.is_published OR t.owner_user_id = auth.uid())
  ));

DROP POLICY IF EXISTS theme_images_own_write ON public.theme_images;
CREATE POLICY theme_images_own_write ON public.theme_images
  FOR ALL TO authenticated
  USING (EXISTS (
    SELECT 1 FROM public.themes t WHERE t.id = theme_images.theme_id AND t.owner_user_id = auth.uid()
  ))
  WITH CHECK (EXISTS (
    SELECT 1 FROM public.themes t WHERE t.id = theme_images.theme_id AND t.owner_user_id = auth.uid()
  ));

-- The five launch themes. Images are attached by scripts/themes/seed-themes.ts.
INSERT INTO public.themes (slug, name, kind, is_published, sort_order) VALUES
  ('sunset', 'Sunset', 'system', true, 0),
  ('beach', 'Beach', 'system', true, 1),
  ('tropical', 'Tropical', 'system', true, 2),
  ('mountains', 'Mountains', 'system', true, 3),
  ('snow', 'Snow', 'system', true, 4)
ON CONFLICT (slug) DO NOTHING;

-- Published system themes are public imagery: readable before sign-in too
-- (login, onboarding and the shell's first paint).
DROP POLICY IF EXISTS themes_public_read ON public.themes;
CREATE POLICY themes_public_read ON public.themes
  FOR SELECT TO anon
  USING (is_published AND kind = 'system');

DROP POLICY IF EXISTS theme_images_public_read ON public.theme_images;
CREATE POLICY theme_images_public_read ON public.theme_images
  FOR SELECT TO anon
  USING (EXISTS (
    SELECT 1 FROM public.themes t
    WHERE t.id = theme_images.theme_id AND t.is_published AND t.kind = 'system'
  ));
